      ],
      "consultas": [
        "Que evidências locais conectam ponto de medição, mistura do químico e representatividade do sinal de corrosão ou residual?",
        "Em quais cenários transientes de dosagem e pH tornam a leitura local pouco representativa do risco global do sistema?"
      ]
    }
  ]
